const CYRILLIC_TO_LATIN = {
  а: 'a', б: 'b', в: 'v', г: 'h', ґ: 'g', д: 'd', е: 'e', є: 'ie', ж: 'zh', з: 'z', и: 'y', і: 'i', ї: 'i', й: 'i',
  к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts',
  ч: 'ch', ш: 'sh', щ: 'shch', ь: '', ю: 'iu', я: 'ia', ы: 'y', э: 'e', ё: 'io', ъ: '',
};

const PDF_VALUE_TRANSLATIONS = new Map([
  ['так', 'yes'], ['да', 'yes'], ['yes', 'yes'], ['true', 'yes'], ['+', 'yes'],
  ['ні', 'no'], ['нет', 'no'], ['no', 'no'], ['false', 'no'], ['-', 'no'], ['0', 'no'],
  ['немає', 'none'], ['відсутні', 'none'], ['відсутня', 'none'], ['не має', 'none'], ['none', 'none'],
  ['неодружена', 'not married'], ['незаміжня', 'not married'], ['не заміжня', 'not married'], ['не одружена', 'not married'],
  ['одружена', 'married'], ['заміжня', 'married'], ['європейська', 'European'], ['європеєць', 'European'],
  ['україна', 'Ukraine'], ['українка', 'Ukrainian'], ['українець', 'Ukrainian'], ['українська', 'Ukrainian'], ['українське', 'Ukrainian'],
  ['середня освіта', 'secondary education'], ['середня', 'secondary education'], ['вища освіта', 'higher education'], ['вища', 'higher education'],
  ['здоровий', 'healthy'], ['здорова', 'healthy'], ['здорова/ий', 'healthy'], ['касир', 'cashier'], ['продавець', 'retail cashier'],
]);

const transliterateForPdf = value => String(value || '').replace(/[А-Яа-яЁёЄєІіЇїҐґ]/g, char => {
  const lower = char.toLowerCase();
  const transliterated = CYRILLIC_TO_LATIN[lower] ?? char;
  return char === lower ? transliterated : transliterated.charAt(0).toUpperCase() + transliterated.slice(1);
});

const toPdfEnglishValue = value => {
  const normalized = normalizeDisplayValue(value);
  if (!normalized) return '';
  const translated = PDF_VALUE_TRANSLATIONS.get(normalized.trim().toLowerCase());
  return translated || transliterateForPdf(normalized);
};

const resolvePdfValue = (data, keys, { translate = true } = {}) => {
  const normalizedKeys = Array.isArray(keys) ? keys : [keys];
  for (const key of normalizedKeys) {
    const value = normalizeDisplayValue(data?.[key]);
    if (value) return translate ? toPdfEnglishValue(value) : value;
  }
  return '';
};

const resolvePdfAge = data => {
  const explicitAge = resolvePdfValue(data, ['age'], { translate: false });
  if (explicitAge) return explicitAge;
  const birth = resolvePdfValue(data, ['birth', 'birthDate', 'dateOfBirth'], { translate: false });
  const calculatedAge = utilCalculateAge(birth);
  return calculatedAge || '';
};

const normalizePdfYesNo = value => {
  if (value === null || value === undefined) return '';
  const raw = String(value).trim();
  if (!raw) return '';
  const loweredRaw = raw.toLowerCase();
  if (['-', '0'].includes(loweredRaw)) return 'no';

  const normalized = normalizeDisplayValue(value);
  if (!normalized) return '';
  const lowered = normalized.toLowerCase();
  if (['yes', 'true', 'так', 'да', '+'].includes(lowered)) return 'yes';
  if (['no', 'false', 'ні', 'нет', 'не було', 'none', 'немає', 'відсутні'].includes(lowered)) return 'no';
  return toPdfEnglishValue(normalized);
};

const resolvePdfYesNoValue = (data, keys) => {
  const normalizedKeys = Array.isArray(keys) ? keys : [keys];
  for (const key of normalizedKeys) {
    const value = normalizePdfYesNo(data?.[key]);
    if (value) return value;
  }
  return '';
};

const resolvePdfMetric = (data, keys, unit) => {
  const value = resolvePdfValue(data, keys, { translate: false });
  if (!value) return '';
  return new RegExp(`\\b${unit}\\b`, 'i').test(value) ? value : `${value} ${unit}`;
};

const resolvePdfCombinedValue = (data, entries) => {
  const values = entries
    .map(([label, keys]) => {
      const value = resolvePdfValue(data, keys);
      return value ? `${label}: ${value}` : '';
    })
    .filter(Boolean);
  return values.join('; ');
};

const resolvePdfHarmfulHabits = data => {
  const summary = resolvePdfValue(data, ['harmfulHabits', 'badHabits']);
  if (summary) return summary;

  const smoking = normalizePdfYesNo(data?.smoking);
  const alcohol = normalizePdfYesNo(data?.alcohol);
  if (!smoking && !alcohol) return 'no';
  if ([smoking, alcohol].filter(Boolean).every(value => value === 'no')) return 'no';

  return resolvePdfCombinedValue(data, [
    ['Smoking', ['smoking']],
    ['Alcohol', ['alcohol']],
  ]);
};

const resolvePdfMaritalStatus = data => {
  const value = resolvePdfValue(data, ['maritalStatus']);
  if (value === 'no') return 'not married';
  if (value === 'yes') return 'married';
  return value;
};

const resolvePdfBloodType = data => {
  const value = resolvePdfValue(data, ['blood', 'bloodType'], { translate: false }).replace(/\s+/g, '');
  if (!value) return '';
  const match = value.match(/^([1-4])([+-])?$/);
  if (match) {
    const groupMap = { 1: 'O', 2: 'A', 3: 'B', 4: 'AB' };
    return `${groupMap[match[1]]}${match[2] ? ` Rh${match[2] === '-' ? '−' : '+'}` : ''}`;
  }
  return toPdfEnglishValue(value).replace(/Rh-/g, 'Rh−');
};

// Full surname (buildName above also folds in the patronymic) is an internal/contract-system
// field only - spec §2 requires it never reach this client-facing document. The PDF only ever
// shows the first name plus a transliterated surname initial, e.g. "Viktoriia I.".
const resolvePdfNameParts = data => {
  const firstNameRaw = resolvePdfValue(data, ['name', 'firstName'], { translate: false });
  const surnameRaw = resolvePdfValue(data, ['surname', 'lastName'], { translate: false });
  const firstName = transliterateForPdf(firstNameRaw);
  const lastInitial = surnameRaw ? transliterateForPdf(surnameRaw.trim().charAt(0)) : '';
  return { firstName, lastInitial };
};

const resolvePdfDisplayName = data => {
  const { firstName, lastInitial } = resolvePdfNameParts(data);
  return [firstName, lastInitial ? `${lastInitial}.` : ''].filter(Boolean).join(' ');
};

const resolvePdfNationality = data => resolvePdfValue(data, ['nationality']) || 'Ukrainian';

// Curated order (spec §3), not the order fields happen to sit in the database.
// "At a glance": 4 cards - the vitals a coordinator scans first.
const buildProfileGlanceRows = data => ([
  ['Age', resolvePdfAge(data)],
  ['Height', resolvePdfMetric(data, ['height'], 'cm')],
  ['Weight', resolvePdfMetric(data, ['weight'], 'kg')],
  ['Blood type', resolvePdfBloodType(data)],
]).filter(([, value]) => value);

// "Background". "Number of children" is intentionally absent - there is no such field distinct
// from `ownKids` (which is "number of deliveries", i.e. Number of pregnancies) in the current
// candidate data model; spec §3 only asks for it "if present in the data".
const buildProfileBackgroundRows = data => ([
  ['Marital status', resolvePdfMaritalStatus(data)],
  ['Number of pregnancies', resolvePdfValue(data, ['ownKids'], { translate: false })],
  ['Previous surrogacy experience', resolvePdfYesNoValue(data, ['surrogacyExperience', 'experienceInSurrogacy'])],
  ['Caesarean section', resolvePdfYesNoValue(data, ['csection', 'cSection', 'c_section', 'cesareanSection'])],
]).filter(([, value]) => value);

// "Personal".
const buildProfilePersonalRows = data => ([
  ['Profession', resolvePdfValue(data, ['profession', 'specialization'])],
  ['Education', resolvePdfValue(data, ['education'])],
  ['Nationality', resolvePdfNationality(data)],
  ['Harmful habits', resolvePdfHarmfulHabits(data)],
]).filter(([, value]) => value);

// spec §7: UKRCOM-SMProfile-{CandidateFirstName}{LastNameInitial}-YYYY-MM-DD.pdf
const buildProfilePdfFileName = data => {
  const { firstName, lastInitial } = resolvePdfNameParts(data);
  const safeName = `${firstName}${lastInitial}`.replace(/[^a-zA-Z0-9-]+/g, '') || 'Profile';
  const dateStamp = new Date().toISOString().slice(0, 10);
  return `UKRCOM-SMProfile-${safeName}-${dateStamp}.pdf`;
};

const renderInfoSection = (title, rows) => (rows.length ? (
  <View style={profilePdfStyles.infoSection}>
    <Text style={profilePdfStyles.infoSectionTitle}>{sanitizePdfText(title)}</Text>
    {rows.map(([label, value], index) => (
      <View
        key={label}
        style={[profilePdfStyles.infoRow, index === 0 ? profilePdfStyles.infoRowFirst : null]}
        wrap={false}
      >
        <View style={profilePdfStyles.infoLabelCell}><Text style={profilePdfStyles.infoLabelText}>{sanitizePdfText(label)}</Text></View>
        <View style={profilePdfStyles.infoValueCell}><Text style={profilePdfStyles.infoValueText}>{sanitizePdfText(value)}</Text></View>
      </View>
    ))}
  </View>
) : null);

// `intendedParentNames`, if given, becomes the small corner tag "Prepared exclusively for {names}
// — Confidential" in the header metadata (spec §1) - replacing the old full-page diagonal
// watermark entirely, not just relabeling it. There is no field on the candidate record itself
// that names the intended parents she's being presented to (that association isn't part of this
// data model - spec §8 keeps DB schema changes out of scope), so the coordinator is prompted for
// it at export time in ProfilePdfExportButton below; the tag still degrades to plain
// "Confidential" if left blank rather than reading "Prepared exclusively for  —  Confidential".
const ProfilePdfDocument = ({ userData, photoUrls, intendedParentNames }) => {
  const glanceRows = buildProfileGlanceRows(userData);
  const backgroundRows = buildProfileBackgroundRows(userData);
  const personalRows = buildProfilePersonalRows(userData);
  const photos = Array.isArray(photoUrls) ? photoUrls : [];
  const photoEntries = photos.map(photo => (
    photo && typeof photo === 'object' ? photo : { src: photo }
  )).filter(photo => photo?.src);
  const dateLabel = formatDisplayDate(new Date());
  const displayName = resolvePdfDisplayName(userData);
  const cornerTag = intendedParentNames
    ? `Prepared exclusively for ${intendedParentNames} — Confidential`
    : 'Confidential';
  const summaryText = typeof userData?.moreInfo_main === 'string' ? userData.moreInfo_main.trim() : '';

  return (
    <Document title={`${displayName || 'Profile'} - UKRCOM Surrogate Mother Profile`} subject="Surrogate mother profile" creator="UKRCOM">
      <Page size="A4" style={profilePdfStyles.page} wrap>
        <BronzeMotif />
        <BrandRow metaLines={[dateLabel, cornerTag]} />
        <BrandRule />
        <TitleBlock
          eyebrow="Surrogate Mother Profile"
          title={displayName || 'Surrogate Mother Profile'}
          subtitle={`${resolvePdfNationality(userData)} · medically approved by our clinical team`}
        />
        {glanceRows.length ? (
          <View style={profilePdfStyles.glanceRow} wrap={false}>
            {glanceRows.map(([label, value]) => (
              <View key={label} style={profilePdfStyles.glanceCard}>
                <Text style={profilePdfStyles.glanceLabel}>{sanitizePdfText(label)}</Text>
                <Text style={profilePdfStyles.glanceValue}>{sanitizePdfText(value)}</Text>
              </View>
            ))}
          </View>
        ) : null}
        {renderInfoSection('Background', backgroundRows)}
        {renderInfoSection('Personal', personalRows)}
        {/* Coordinator's summary (spec §4): moreInfo_main rendered verbatim, section omitted
            entirely (not shown empty) when the field has nothing in it. */}
        {/* Signature sits right under the card, not above it as PreparedForBlock does elsewhere
            (spec §4: "signature under the text") - so it reads as who wrote this note. */}
        <SummaryCard label="Coordinator's summary" text={summaryText} />
        {summaryText ? <CoordinatorLine /> : null}
        <Footer />
      </Page>
      {photoEntries.map((photo, index) => (
        <Page key={`${photo.src}-${index}`} size="A4" style={profilePdfStyles.imagePage}>
          <Text style={profilePdfStyles.photoCounter}>{sanitizePdfText(`${index + 1} of ${photoEntries.length}`)}</Text>
          <View style={profilePdfStyles.profileImageWrap}>
            <Image src={photo.src} style={profilePdfStyles.profileImage} />
          </View>
          {/* photo-context caption (spec §5): only rendered when the photo entry actually carries
              one from the data - never invented here. */}
          {photo.caption || photo.context ? (
            <Text style={profilePdfStyles.photoContext}>{sanitizePdfText(photo.caption || photo.context)}</Text>
          ) : null}
          <Footer />
        </Page>
      ))}
    </Document>
  );
};

const pdfExportButtonStyle = {
  ...compactTopActionButtonStyle,
  backgroundColor: '#455a64',
  color: '#fff',
  textDecoration: 'none',
};

const resolvePdfPhotoUrls = async ({ cardData, photoUrls }) => {
  const existingPhotos = Array.isArray(photoUrls) ? photoUrls : [];

  if (!cardData?.userId) {
    return existingPhotos;
  }

  const { items: storageFiles } = await getUserStorageAvatarPhotoFiles(cardData.userId);
  const storagePhotos = storageFiles.map(file => file.dataUrl).filter(Boolean);
  if (storagePhotos.length) {
    return Array.from(new Set(storagePhotos));
  }

  let databasePhotos = [];
  try {
    databasePhotos = await getAllUserPhotos(cardData.userId, { includeStorage: false });
  } catch (error) {
    console.error('Unable to load PDF fallback photos', error);
  }

  const combinedPhotos = filterOutMedicationPhotos([...existingPhotos, ...databasePhotos], cardData.userId)
    .map(convertDriveLinkToImage)
    .filter(Boolean);
  return Array.from(new Set(combinedPhotos));
};

const readBlobAsDataUrl = blob => new Promise((resolve, reject) => {
  const reader = new FileReader();
  reader.onloadend = () => resolve(typeof reader.result === 'string' ? reader.result : '');
  reader.onerror = () => reject(reader.error);
  reader.readAsDataURL(blob);
});

const loadPdfEmbeddedImage = async photoUrl => {
  const result = await resolvePdfEmbeddedImageSource(photoUrl);
  if (!result.src) return result;
  const normalizedSrc = await reencodePdfImageDataUrl(result.src);
  return { ...result, src: normalizedSrc };
};

const resolvePdfEmbeddedImageSource = async photoUrl => {
  if (!photoUrl) {
    return { src: '' };
  }

  if (String(photoUrl).startsWith('data:image/')) {
    return { src: photoUrl };
  }

  try {
    const response = await fetch(photoUrl);
    if (!response.ok) {
      throw new Error(`Photo request failed with status ${response.status}`);
    }
    const blob = await response.blob();
    const dataUrl = await readBlobAsDataUrl(blob);
    if (!dataUrl.startsWith('data:image/')) {
      return { src: '' };
    }
    return { src: dataUrl };
  } catch (error) {
    // Remote URLs are never handed to @react-pdf: its own fetch would hit the
    // same CORS wall and abort rendering of the whole document.
    console.error('Unable to load PDF photo', photoUrl, error);
    return { src: '' };
  }
};

const isSurrogateMotherRole = data => String(data?.userRole || data?.role || '').trim().toLowerCase() === 'sm';

const ProfilePdfExportButton = ({ cardData, photoUrls }) => {
  const [isGenerating, setIsGenerating] = useState(false);

  const handleExport = async event => {
    event.stopPropagation();
    if (isGenerating) return;

    // spec §1: the corner "Prepared exclusively for {intended parent names}" tag needs a name
    // that isn't part of the candidate record itself (this document describes her, it isn't tied
    // to one specific match) - ask once per export; the tag falls back to plain "Confidential"
    // if this is left blank.
    const intendedParentNames = (window.prompt(
      'Intended parent name(s) for "Prepared exclusively for…" (leave blank to omit):',
      ''
    ) || '').trim();

    setIsGenerating(true);
    const fileName = buildProfilePdfFileName(cardData);

    const downloadBlob = blob => {
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    };

    try {
      // The document's wordmark/footer identity comes from budget/technical/agency - this export
      // path doesn't otherwise load the budget catalog, so fetch it before rendering.
      await ensurePdfAgencyConfigLoaded();
      const effectivePhotoUrls = await resolvePdfPhotoUrls({ cardData, photoUrls });
      const embeddedPhotoEntries = await Promise.all(
        effectivePhotoUrls.map(photoUrl => loadPdfEmbeddedImage(photoUrl))
      );
      const printablePhotoEntries = embeddedPhotoEntries.filter(entry => entry?.src);
      const blob = await pdf(
        <ProfilePdfDocument userData={cardData} photoUrls={printablePhotoEntries} intendedParentNames={intendedParentNames} />
      ).toBlob();
      downloadBlob(blob);
    } catch (error) {
      console.error('Unable to export profile PDF', error);
      try {
        const fallbackBlob = await pdf(
          <ProfilePdfDocument userData={cardData} photoUrls={[]} intendedParentNames={intendedParentNames} />
        ).toBlob();
        downloadBlob(fallbackBlob);
      } catch (fallbackError) {
        console.error('Unable to produce fallback PDF', fallbackError);
        toast.error('Не вдалося експортувати PDF');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <button
      type="button"
      style={pdfExportButtonStyle}
      title="Експорт профілю в PDF"
      aria-label="Експорт профілю в PDF"
      onClick={handleExport}
      disabled={isGenerating}
    >
      {isGenerating ? (
        <span style={{ fontSize: '10px', fontWeight: 700 }}>...</span>
      ) : (
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M7 3h7l4 4v14H7V3z" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" />
          <path d="M14 3v5h4" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" />
          <path d="M9 13h6M9 16h6M9 19h3" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
        </svg>
      )}
    </button>
  );
};

// Фото картки без жодного фото питаються раз на вкладку, а не на кожен
// рендер. Ефект нижче залежить від `cardData` — нового обʼєкта щоразу, як
// список отримує наступну порцію, — і кожна порція перезапускала лістинг
// Storage для кожної такої картки. Відповідь «фото немає» теж памʼятається:
// інакше картка без фото питала б щоразу заново. Свіжі фото відкритої
// анкети читає форма (`Photos`), а не ця памʼять.
const topBlockPhotoRequests = new Map();
const requestTopBlockPhotos = userId => {
  let pending = topBlockPhotoRequests.get(userId);
  if (!pending) {
    pending = getAllUserPhotos(userId).catch(error => {
      topBlockPhotoRequests.delete(userId);
      throw error;
    });
    topBlockPhotoRequests.set(userId, pending);
  }
  return pending;
};

export const TopBlock = ({
  userData,
  setUsers,
  setShowInfoModal,
  setState,
  setUserIdToDelete,
  isFromListOfUsers,
  favoriteUsers = {},
  setFavoriteUsers,
  dislikeUsers = {},
  setDislikeUsers = () => {},
  currentFilter,
  isDateInRange,
  onOpenMedications,
  setSearch = null,
  topBlueAction = null,
  additionalActions = null,
  overlayFieldAdditions = {},
  onSubmitHistorySnapshot = null,
  stimulationScheduleToggle = null,
  // Batch 26 §8: shows FieldComment's backend-navigation arrow
  // (multiData/comments/{ownerId}/{cardId}) when
  // on - off by default so a caller that hasn't wired up the toggle (no regression) keeps today's
  // arrow-free look; AddNewProfile.jsx passes its own persisted toggle state.
  extendedMode = false
}) => {
  const [editableComment, setEditableComment] = React.useState('');
  const [isCommentModalOpen, setIsCommentModalOpen] = React.useState(false);
  const [selectedComment, setSelectedComment] = React.useState(null);
  const [commentToDelete, setCommentToDelete] = React.useState(null);
  const [isRoleEditorOpen, setIsRoleEditorOpen] = React.useState(false);
  const [isPhotosModalOpen, setIsPhotosModalOpen] = React.useState(false);
  const containerRef = useRef(null);
  const [needsOwnSurface, setNeedsOwnSurface] = useState(false);
  const [backendMultiComments, setBackendMultiComments] = React.useState([]);
  // Публічні відгуки про цю людину — `comments/{profileId}`. Сусіди по списку,
  // але не сусіди по суті: нотатка належить тому, хто її написав, а відгук —
  // усій базі, і читається він одним запитом на картку, а не по власниках.
  const [publicComments, setPublicComments] = React.useState([]);
  const [publicCommentsFailed, setPublicCommentsFailed] = React.useState(false);
  const [publicCommentsLoading, setPublicCommentsLoading] = React.useState(false);
  const publicCommentsRequestRef = React.useRef(0);
  const isAdmin = isAdminUid(auth.currentUser?.uid);
  const cardData = React.useMemo(() => {
    if (!userData) return null;
    return { ...userData, cycleStatus: getEffectiveCycleStatus(userData) };
  }, [userData]);
  const localMultiDataComments = extractMultiDataComments(cardData);
  const multiDataComments = React.useMemo(() => {
    const fromLocal = localMultiDataComments.map(item => ({
      ...item,
      source: 'local',
    }));
    const fromBackend = backendMultiComments.map(item => ({
      commentId: item.ownerId || '',
      text: item.text,
      authorId: item.ownerId || '',
      ownerId: item.ownerId || '',
      source: 'backend',
      lastAction: Number(item.lastAction) || 0,
    }));
    const combined = [...fromLocal, ...fromBackend];
    const uniq = new Map();
    combined.forEach(comment => {
      const key = `${comment.commentId || ''}|${comment.authorId || ''}|${comment.text || ''}`;
      if (!uniq.has(key)) {
        uniq.set(key, comment);
      }
    });
    return Array.from(uniq.values());
  }, [localMultiDataComments, backendMultiComments]);
  // FieldComment already renders (and edits) the current admin's own multiData
  // comment as an input, so drop it here to avoid showing it a second time as
  // a read-only line right underneath.
  const otherAdminsComments = React.useMemo(() => {
    const currentUid = auth.currentUser?.uid || '';
    return multiDataComments.filter(comment => (comment.ownerId || comment.authorId || '') !== currentUid);
  }, [multiDataComments]);
  // `region` теж буває масивом версій: без розгортання `normalizeRegion` його
  // пропускав, і «область» не дописувалась. Адмін бачить усі версії.
  const region = formatValueVersions(cardData.region, normalizeRegion);
  const showSideActions = !additionalActions;
  const hasHiddenCycleFieldRole = hasRoleWithoutCycle(cardData);
  const userPhotoUrls = getUserProfilePhotoUrls(cardData);
  const userPhotoUrl = userPhotoUrls[0] || '';

  // Measured once the block is in the DOM: only when nothing behind it paints a
  // colour dark enough for white text does it draw its own surface.
  useLayoutEffect(() => {
    if (typeof window === 'undefined' || typeof window.getComputedStyle !== 'function') return;
    const parent = containerRef.current?.parentElement;
    if (!parent) return;
    setNeedsOwnSurface(findPaintedAncestorSurface(parent) !== 'colored');
  }, []);

  React.useEffect(() => {
    // Компонент може бути перевикористаний для іншої картки: старі рядки не
    // мають лишатися клікабельними, поки новий запит ще в дорозі.
    setBackendMultiComments([]);
    setPublicComments([]);
    setPublicCommentsFailed(false);
    setPublicCommentsLoading(false);
    publicCommentsRequestRef.current += 1;
    if (!cardData?.userId) {
      return;
    }
    let isMounted = true;
    const loadAllComments = async () => {
      const viewerId = auth.currentUser?.uid;
      const viewerProfile = viewerId ? (getCard(viewerId) || await fetchUserById(viewerId)) : null;
      // Власну нотатку читає й показує `FieldComment` під цим блоком, а тут
      // її однаково відкидає `otherAdminsComments` — тож питати її вдруге
      // означало зайвий запит на кожну картку списку.
      const ownerIds = resolveMatchingMultiDataOwnerIds({ viewerId, profile: viewerProfile })
        .filter(ownerId => ownerId !== viewerId);
      if (!ownerIds.length) return;
      const allByCard = await fetchAllCommentsByCardId(cardData.userId, ownerIds);
      if (!isMounted) return;
      setBackendMultiComments(allByCard);
    };
    loadAllComments();
    return () => {
      isMounted = false;
    };
  }, [cardData?.userId]);

  // Відгуки приїжджають разом із карткою, а не на окремий дотик: блок картки —
  // робоче місце адміністраторки, і «що про цю людину вже написали» вона мусить
  // бачити відкритою карткою, а не перевіряти кнопкою. Кнопка лишилась одна — на
  // повтор після відмови.
  const loadPublicComments = React.useCallback(async ({ force = false } = {}) => {
    const profileId = cardData?.userId;
    if (!profileId) return;
    const requestId = publicCommentsRequestRef.current + 1;
    publicCommentsRequestRef.current = requestId;
    setPublicCommentsFailed(false);
    setPublicCommentsLoading(true);
    try {
      const comments = await readPublicCommentsCached(profileId, { force });
      if (publicCommentsRequestRef.current !== requestId) return;
      setPublicComments(comments);
    } catch (error) {
      if (publicCommentsRequestRef.current !== requestId) return;
      setPublicCommentsFailed(true);
      // Читання падає одразу для всіх карток списку (найчастіше це невикочені
      // правила), тож тост має стабільний id: сказати про це досить один раз,
      // а не десятком однакових вікон одне на одному.
      toast.error(`Не вдалося завантажити публічні відгуки: ${error?.message || error}`, {
        id: 'public-comments-load-failed',
      });
    } finally {
      if (publicCommentsRequestRef.current === requestId) setPublicCommentsLoading(false);
    }
  }, [cardData?.userId]);

  React.useEffect(() => {
    loadPublicComments();
  }, [loadPublicComments]);

  const retryPublicComments = event => {
    event?.stopPropagation();
    loadPublicComments({ force: true });
  };

  React.useEffect(() => {
    if (!cardData?.userId || userPhotoUrls.length > 0) {
      return undefined;
    }

    let isMounted = true;
    const hydrateTopBlockPhotos = async () => {
      try {
        const urls = await requestTopBlockPhotos(cardData.userId);
        if (!isMounted) return;
        const filteredUrls = filterOutMedicationPhotos(urls, cardData.userId);
        if (!filteredUrls.length) return;

        const updatePhotos = currentCard => {
          const baseCard = currentCard || cardData;
          if (baseCard?.userId && baseCard.userId !== cardData.userId) return currentCard;
          const currentUrls = getUserProfilePhotoUrls(baseCard);
          if (currentUrls.length > 0) return currentCard || baseCard;
          return {
            ...baseCard,
            photos: filteredUrls,
            __photosHydrated: true,
          };
        };

        if (typeof setState === 'function' && !isFromListOfUsers) {
          setState(prev => updatePhotos(prev), {
            source: 'userChange',
            caller: 'renderTopBlock.hydrateTopBlockPhotos',
            reason: 'photos-hydrated-on-open',
          });
        }

        if (typeof setUsers === 'function') {
          setUsers(prev => (
            stateContainsUser(prev, cardData.userId)
              ? updateUserInState(prev, cardData.userId, updatePhotos)
              : prev
          ));
        }
      } catch (error) {
        if (isMounted) {
          console.error('Error hydrating top block photos:', error);
        }
      }
    };

    hydrateTopBlockPhotos();
    return () => {
      isMounted = false;
    };
  }, [cardData, isFromListOfUsers, setState, setUsers, userPhotoUrls.length]);

  if (!cardData) return null;

  const setCardPhotosState = updater => {
    const resolveNextCard = currentCard => {
      const baseCard = currentCard || cardData;
      return typeof updater === 'function' ? updater(baseCard) : updater;
    };

    if (typeof setUsers === 'function' && cardData.userId) {
      setUsers(prev => (
        stateContainsUser(prev, cardData.userId)
          ? updateUserInState(prev, cardData.userId, currentCard => resolveNextCard(currentCard))
          : prev
      ));
    }

    if (typeof setState === 'function' && !isFromListOfUsers) {
      setState(prev => resolveNextCard(prev), {
        source: 'userChange',
        caller: 'renderTopBlock.photosModal',
        reason: 'photos-updated',
      });
    }
  };

  const renderOverlayEntries = fieldNames => {
    const normalizedFieldNames = Array.isArray(fieldNames) ? fieldNames : [fieldNames];
    const entries = normalizedFieldNames.flatMap(fieldName =>
      (overlayFieldAdditions?.[fieldName] || []).map(entry => ({ ...entry, fieldName }))
    );

    if (!entries.length) return null;

    return entries.map((entry, idx) => (
      <div
        key={`${entry.fieldName}-${entry.editorUserId || 'unknown'}-${entry.value}-${idx}`}
        style={entry.isDeleted ? deletedOverlayEntryStyle : addedOverlayEntryStyle}
      >
        <strong>{entry.fieldName}:</strong> {entry.value}
      </div>
    ));
  };

  const submitOptions = { onSubmitHistorySnapshot };

  // Хто може правити публічний відгук: його автор і адмін — рівно те саме коло,
  // що й у правилі бази на `comments/{profileId}/{commentId}`. Чужий відгук у
  // цьому списку читається, але не відкривається на правку.
  const canModifyPublicComment = comment => (
    isAdmin || (Boolean(comment?.authorId) && comment.authorId === (auth.currentUser?.uid || ''))
  );

  const savePublicComment = async () => {
    const prepared = editableComment.trim();
    const commentId = selectedComment?.commentId || '';
    if (!commentId) {
      toast.error('Не обрано відгук для редагування');
      return;
    }
    try {
      // Порожній текст — це і є зняття запису: інакше відгук нічим не
      // прибрати, і він лишався б назавжди (те саме правило, що й у стрічці).
      // Запис іде через чергу пристрою (`delivered`): адмінка чекає на базу,
      // бо тут тост каже «збережено», а не «поставлено в чергу».
      const { delivered, deleted, ...updated } = await updatePublicProfileComment({
        profileId: cardData.userId,
        commentId,
        text: prepared,
      }) || {};
      await delivered;
      dropCachedPublicComments(cardData.userId);
      setPublicComments(prev => (!deleted
        ? prev.map(item => (item.id === commentId
          ? { ...item, text: updated.text, updatedAt: updated.updatedAt }
          : item))
        : prev.filter(item => item.id !== commentId)));
      toast.success(!deleted ? 'Публічний відгук збережено' : 'Публічний відгук видалено');
      setIsCommentModalOpen(false);
      setSelectedComment(null);
    } catch (error) {
      toast.error(`Не вдалося зберегти публічний відгук: ${error?.message || error}`);
    }
  };

  const saveMultiComment = async () => {
    if (selectedComment?.kind === 'public') {
      await savePublicComment();
      return;
    }
    const prepared = editableComment.trim();
    const targetCommentId = selectedComment?.commentId || '';
    const currentUid = auth.currentUser?.uid || '';
    if (!targetCommentId) {
      toast.error('Не обрано коментар для редагування');
      return;
    }
    if (selectedComment?.ownerId && selectedComment.ownerId !== currentUid && !isAdmin) {
      toast.error('Недостатньо прав для редагування цього коментаря');
      return;
    }
    const updatedComments = (multiDataComments || []).map(comment =>
      comment.commentId === targetCommentId ? { ...comment, text: prepared } : comment
    );
    const optimisticCard = {
      ...cardData,
      multiData: {
        ...(cardData.multiData || {}),
        comments: updatedComments.map(comment => ({
          commentId: comment.commentId,
          text: comment.text,
          authorId: comment.authorId || '',
        })),
      },
    };
    if (typeof setUsers === 'function') {
      setUsers(prev => {
        if (Array.isArray(prev)) {
          return updateUserInState(prev, cardData.userId, () => optimisticCard);
        }
        return updateUserInState(prev, cardData.userId, () => optimisticCard);
      });
    }
    if (typeof setState === 'function' && !isFromListOfUsers) {
      setState(prev => ({ ...prev, ...optimisticCard }));
    }

    let result = null;
    if (selectedComment?.ownerId) {
      result = await updateCommentByOwner({
        ownerId: selectedComment.ownerId,
        cardId: cardData.userId,
        text: prepared,
      });
    } else {
      result = await persistUserComment(cardData.userId, prepared);
    }
    if (!result) {
      toast.error('Не вдалося зберегти коментар в multiData');
      return;
    }
    setBackendMultiComments(prev =>
      prev.map(item =>
        (item.ownerId || '') === (selectedComment?.ownerId || '')
          ? { ...item, text: prepared, lastAction: result.lastAction || Date.now() }
          : item
      )
    );
    toast.success('Коментар в multiData збережено');
    setIsCommentModalOpen(false);
    setSelectedComment(null);
  };

  const handleDeleteComment = async comment => {
    if (comment?.kind === 'public') {
      if (!canModifyPublicComment(comment)) {
        toast.error('Видалення недоступне');
        return;
      }
      try {
        const { delivered } = await deletePublicProfileComment({ profileId: cardData.userId, commentId: comment.commentId }) || {};
        await delivered;
        dropCachedPublicComments(cardData.userId);
        setPublicComments(prev => prev.filter(item => item.id !== comment.commentId));
        toast.success('Публічний відгук видалено');
      } catch (error) {
        toast.error(`Не вдалося видалити публічний відгук: ${error?.message || error}`);
      }
      return;
    }
    if (!isAdmin || !comment?.ownerId) {
      toast.error('Видалення недоступне');
      return;
    }
    const isDeleted = await deleteCommentByOwner({
      ownerId: comment.ownerId,
      cardId: cardData.userId,
    });
    if (!isDeleted) {
      toast.error('Не вдалося видалити коментар');
      return;
    }
    setBackendMultiComments(prev =>
      prev.filter(item => item.ownerId !== comment.ownerId)
    );
    toast.success('Коментар видалено');
  };

  const formatCommentDate = timestamp => {
    const normalizedTimestamp = Number(timestamp);
    if (!Number.isFinite(normalizedTimestamp) || normalizedTimestamp <= 0) return '';
    const date = new Date(normalizedTimestamp);
    if (Number.isNaN(date.getTime())) return '';
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = String(date.getFullYear());
    return `${day}.${month}.${year}`;
  };

  const openAuthorCardForEdit = async authorId => {
    if (!authorId) {
      toast.error('Немає автора для цього коментаря');
      return;
    }
    if (typeof setSearch !== 'function' || typeof setState !== 'function') {
      toast.error('Режим редагування недоступний у цьому контексті');
      return;
    }
    setSearch(authorId);
    const cachedAuthorCard = getCard(authorId);
    setState(cachedAuthorCard || { userId: authorId }, {
      source: cachedAuthorCard ? 'localStorage' : 'userChange',
      caller: 'renderTopBlock.openAuthorCardForEdit',
      reason: 'open-author-local-first',
    });
  };

  const refreshCardFromBackend = async () => {
    let fresh = null;
    let toastFn = toast.error;
    let toastMsg = 'Не вдалося завантажити дані';
    try {
      // Перечитується те джерело, де анкета справді лежить: у чернетки це
      // `multiData/profileMutations`, а не вузли готової анкети — ті для неї
      // порожні, і доти тут виходило «Свіжі дані відсутні» над старим знімком.
      fresh = await fetchProfileRecordById(cardData.userId, {
        prefer: isDraftProfileRecord(cardData) ? 'draft' : '',
        creatorUid: getDraftRecordCreator(cardData),
      });
      if (fresh) {
        clearCardCache(cardData.userId);
        updateCard(cardData.userId, fresh);
        const backendCard = { ...fresh, userId: cardData.userId };
        rememberDraftRecordRevision(backendCard);

        if (setUsers) {
          setUsers(prev => {
            return updateUserInState(prev, cardData.userId, () => backendCard);
          });
        }

        if (setState && !isFromListOfUsers) {
          // Рядки, які адмін щойно додав «+» і ще не заповнив, у базі не лежать
          // (`keepUnsavedFieldRows`): без цього перечитування мовчки їх знімало.
          setState(prevState => keepUnsavedFieldRows(prevState, backendCard), {
            source: 'backend',
            caller: 'renderTopBlock.detailsRefreshButton',
            reason: 'manual-backend-refresh',
          });
        }

        console.log('[ProfileSnapshotDebug][renderTopBlock]', {
          source: 'backend',
          caller: 'details-refresh-button',
          userId: cardData.userId,
          fieldsCount: Object.keys(backendCard).length,
          applied: true,
          timestamp: new Date().toISOString(),
        });
        toastFn = toast.success;
        toastMsg = `Дані завантажено з бекенду (${Object.keys(backendCard).length} полів)`;
      } else {
        toastMsg = 'Свіжі дані відсутні';
      }
    } catch (error) {
      console.error(error);
      toastMsg = error.message || 'Не вдалося завантажити дані';
    } finally {
      toastFn(toastMsg);
    }
  };

  const cardRole = cardData.role || cardData.userRole;
  const displayRole = cardRole || 'role';
  const identityMeta = renderIdentityMeta(cardData);
  const updateContext = {
    mode: isFromListOfUsers ? 'list' : 'single',
    userId: cardData.userId,
    setCurrentUser: setState,
    setUserCollection: setUsers,
  };

  const deliveryInfo = fieldDeliveryInfo({
    userData: cardData,
    setUsers,
    setState,
    submitOptions,
    updateContext,
  });

  // Кнопка «усі поля» — перемикач: перше натискання розгортає блок і
  // перечитує анкету з бекенду (відкрита картка береться з кеша, і сумнів у
  // її свіжості — саме те, з чим сюди приходять), друге — згортає. Доти вона
  // вміла лише показувати, і сховати розгорнуте було нічим, крім
  // перезавантаження сторінки.
  const handleDetailsRefresh = async event => {
    event.stopPropagation();
    const details = document.getElementById(cardData.userId);
    if (details && details.style.display === 'block') {
      details.style.display = 'none';
      return;
    }
    if (details) {
      details.style.display = 'block';
      details.style.marginTop = '8px';
      const bg = getParentBackground(details);
      details.style.color = getContrastColor(bg);
    }

    // Дані поза анкетою (нотатки, відгуки, реакції, доповнення) читаються
    // разом з анкетою, а не слідом: блок показує обидві половини.
    await Promise.all([
      refreshCardFromBackend(),
      loadCardBackendExtras(cardData.userId),
    ]);
    // Форма адміна тримає пропозиції редакторів окремо від анкети, і вони
    // так само могли застаріти — хай перечитає і їх.
    if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
      window.dispatchEvent(new CustomEvent(PROFILE_BACKEND_REFRESH_EVENT, { detail: { userId: cardData.userId } }));
    }
  };

  const blueActionElement = topBlueAction ? (
    <button
      type="button"
      onClick={event => {
        event.stopPropagation();
        if (typeof topBlueAction.onClick === 'function') {
          topBlueAction.onClick(cardData);
        }
      }}
      style={{ ...zoneActionButtonStyle, backgroundColor: '#0288d1', color: '#fff' }}
      aria-label={topBlueAction.ariaLabel || topBlueAction.title || 'Синя кнопка'}
      title={topBlueAction.title || topBlueAction.ariaLabel || 'Синя кнопка'}
    >
      {topBlueAction.icon}
    </button>
  ) : (
    isFromListOfUsers &&
    typeof setSearch === 'function' &&
    btnEdit(
      cardData,
      setSearch,
      setState,
      { ...zoneActionButtonStyle, backgroundColor: '#0288d1', color: '#fff' },
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
        <path d="M4 20h4l10-10-4-4L4 16v4z" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" />
        <path d="M13 7l4 4" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
      </svg>
    )
  );

  const getInTouchReactionActions = (
    <>
      <button
        type="button"
        style={{
          ...compactReactionButtonStyle,
          backgroundColor: '#d32f2f',
          border: 'none',
          color: '#fff',
        }}
        onClick={event => {
          event.stopPropagation();
          handleChange(
            setUsers,
            setState,
            cardData.userId,
            'getInTouch',
            '',
            true,
            { currentFilter, isDateInRange, ...submitOptions },
          );
        }}
        disabled={!cardData?.userId}
        title="Видалити дату контакту"
        aria-label="Видалити дату контакту"
      >
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M6 6l12 12M18 6L6 18" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
        </svg>
      </button>
      <BtnDislike
        title="Дизлайк"
        ariaLabel="Дизлайк"
        userId={cardData.userId}
        userData={cardData}
        dislikeUsers={dislikeUsers}
        setDislikeUsers={setDislikeUsers}
        onDislikeAdded={() =>
          handleChange(
            setUsers,
            setState,
            cardData.userId,
            'getInTouch',
            '2099-99-99',
            true,
            { currentFilter, isDateInRange, ...submitOptions },
          )
        }
        onDislikeRemoved={() =>
          handleChange(
            setUsers,
            setState,
            cardData.userId,
            'getInTouch',
            '',
            true,
            { currentFilter, isDateInRange, ...submitOptions },
          )
        }
        favoriteUsers={favoriteUsers}
        setFavoriteUsers={setFavoriteUsers}
        customStyle={{
          ...compactReactionButtonStyle,
          backgroundColor: '#ef6c00',
          border: 'none',
        }}
        inactiveIconColor="#fff"
        activeIconColor="#1f2937"
        iconSize={11}
        activeBorderWidth={2}
        activeBoxShadowWidth={1}
      />
      <BtnFavorite
        title="В обране"
        ariaLabel="В обране"
        userId={cardData.userId}
        userData={cardData}
        favoriteUsers={favoriteUsers}
        setFavoriteUsers={setFavoriteUsers}
        dislikeUsers={dislikeUsers}
        setDislikeUsers={setDislikeUsers}
        onDislikeRemoved={() =>
          handleChange(
            setUsers,
            setState,
            cardData.userId,
            'getInTouch',
            '',
            true,
            { currentFilter, isDateInRange, ...submitOptions },
          )
        }
        customStyle={{
          ...compactReactionButtonStyle,
          backgroundColor: '#f9a825',
          border: 'none',
        }}
        inactiveIconColor="#fff"
        activeIconColor="#1f2937"
        iconSize={11}
        activeBorderWidth={2}
        activeBoxShadowWidth={1}
      />
    </>
  );

  const stimulationScheduleToggleTitle = stimulationScheduleToggle?.visible
    ? 'Приховати графік стимуляції'
    : 'Показати графік стимуляції';

  const stimulationScheduleToggleButton = stimulationScheduleToggle ? (
    <button
      type="button"
      onClick={event => {
        event.stopPropagation();
        if (typeof stimulationScheduleToggle.onToggle === 'function') {
          stimulationScheduleToggle.onToggle(cardData);
        }
      }}
      style={{
        ...detailsToggleStyle,
        backgroundColor: stimulationScheduleToggle.visible ? '#6a1b9a' : '#455a64',
      }}
      disabled={stimulationScheduleToggle.disabled}
      title={stimulationScheduleToggle.title || stimulationScheduleToggleTitle}
      aria-label={stimulationScheduleToggle.ariaLabel || stimulationScheduleToggleTitle}
      aria-pressed={Boolean(stimulationScheduleToggle.visible)}
    >
      {stimulationScheduleToggle.visible ? (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M4 19V5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <path d="M4 17H20" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <path d="M7 14L11 10L14 13L19 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          <path d="M5 5L19 19" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" />
        </svg>
      ) : (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M4 19V5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <path d="M4 17H20" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <path d="M7 14L11 10L14 13L19 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      )}
    </button>
  ) : null;

  const topActions = [
    {
      key: 'delete',
      color: '#d32f2f',
      content: btnDel(
        cardData,
        setShowInfoModal,
        setUserIdToDelete,
        isFromListOfUsers,
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M4 7h16" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <path d="M9 7V5a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <path d="M7 7l1 12a1 1 0 0 0 1 .9h6a1 1 0 0 0 1-.9L17 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          <path d="M10 11v5M14 11v5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
        </svg>,
        { ...zoneActionButtonStyle, backgroundColor: '#d32f2f', color: '#fff' }
      ),
    },
    typeof onOpenMedications === 'function' && {
      key: 'medications',
      color: '#2e7d32',
      content: (
        <button
          type="button"
          style={{ ...zoneActionButtonStyle, backgroundColor: '#2e7d32', color: '#fff' }}
          onClick={event => {
            event.stopPropagation();
            onOpenMedications(cardData);
          }}
          disabled={!cardData?.userId}
          aria-label="Ліки"
          title="Ліки"
        >
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M8.5 8.5l7 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            <path d="M6.2 10.8a3.25 3.25 0 0 1 4.6-4.6l6.9 6.9a3.25 3.25 0 1 1-4.6 4.6l-6.9-6.9z" stroke="currentColor" strokeWidth="2" />
          </svg>
        </button>
      ),
    },
    blueActionElement && {
      key: 'blue-action',
      color: '#0288d1',
      content: blueActionElement,
    },
  ].filter(action => action && action.content);

  const avatarLabel = userPhotoUrl ? 'Відкрити фото користувача' : 'Додати фото користувача';
  const avatarContent = userPhotoUrl ? (
    <img
      src={userPhotoUrl}
      alt={buildName(cardData) || 'Фото користувача'}
      style={topBlockPhotoStyle}
      loading="lazy"
    />
  ) : (
    <span style={emptyAvatarStyle} aria-hidden="true">
      <svg width="23" height="23" viewBox="0 0 24 24" fill="none">
        <path d="M12 5v14M5 12h14" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" />
      </svg>
    </span>
  );

  return (
    <div
      ref={containerRef}
      style={needsOwnSurface ? { ...topBlockContainerStyle, ...topBlockOwnSurfaceStyle } : topBlockContainerStyle}
    >
      <div style={topBlockHeaderLayoutStyle}>
        <button
          type="button"
          style={topBlockHeaderAvatarButtonStyle}
          onClick={event => {
            event.stopPropagation();
            setIsPhotosModalOpen(true);
          }}
          aria-label={avatarLabel}
          title={avatarLabel}
        >
          {avatarContent}
        </button>
        <div style={topBlockHeaderContentStyle}>
          <div style={cardHeaderStyle}>
            <div style={cardNameRowStyle}>
              <div style={cardNameStyle}>{buildName(cardData)}</div>
              <button
                type="button"
                style={roleBadgeStyle(cardRole)}
                onClick={event => {
                  event.stopPropagation();
                  setIsRoleEditorOpen(open => !open);
                }}
                aria-expanded={isRoleEditorOpen}
                aria-label="Редагувати роль"
                title="Редагувати роль"
              >
                {displayRole}
              </button>
            </div>
            {isRoleEditorOpen && (
              <div style={roleEditorStyle} onClick={event => event.stopPropagation()}>
                {fieldRole({ userData: cardData, setUsers, setState, submitOptions, updateContext })}
              </div>
            )}
            {renderOverlayEntries(['surname', 'name', 'fathersname'])}
            <div style={cardIdRowStyle}>
              {cardData.lastAction && <span>{formatDateToDisplay(normalizeLastAction(cardData.lastAction))}</span>}
              {cardData.lastAction && cardData.userId && <span>·</span>}
              {cardData.userId && (
                // Чернетка лежить не в `users`, а в `multiData/profileMutations`:
                // посилання веде туди, де її дані справді є.
                <a
                  href={getDraftRecordDataSegments(cardData)
                    ? buildRtdbConsoleLink(getDraftRecordDataSegments(cardData))
                    : buildUserRtdbLink(cardData.userId)}
                  target="_blank"
                  rel="noreferrer"
                  title={getDraftRecordDataSegments(cardData) ? 'Відкрити чернетку в Firebase RTDB' : 'Відкрити профіль в Firebase RTDB'}
                  onClick={event => event.stopPropagation()}
                  style={{ color: 'inherit', textDecoration: 'none' }}
                >
                  {cardData.userId}
                </a>
              )}
            </div>
          </div>
          <div style={topButtonsRowStyle}>
            {topActions.map(action => (
              <div
                key={action.key}
                aria-label={action.key}
                style={{ ...topButtonsZoneStyle, backgroundColor: action.color }}
              >
                {action.content}
              </div>
            ))}
            <div style={secondaryActionsStyle}>
              {showSideActions &&
                btnExport(cardData, {
                  ...compactTopActionButtonStyle,
                  backgroundColor: 'green',
                  color: '#fff',
                })}
              {isSurrogateMotherRole(cardData) && (
                <ProfilePdfExportButton cardData={cardData} photoUrls={userPhotoUrls} />
              )}
              {additionalActions}
              {stimulationScheduleToggleButton}
              <button
                type="button"
                onClick={handleDetailsRefresh}
                style={detailsToggleStyle}
                title="Оновити дані з бекенду та показати всі поля (повторно — сховати)"
                aria-label="Оновити дані з бекенду та показати всі поля"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M4 12a8 8 0 0 1 14.93-4H15" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
                  <path d="M20 12a8 8 0 0 1-14.93 4H9" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      </div>
      <div style={statusRowStyle}>
        <div style={getInTouchStatusItemStyle}>
          {fieldGetInTouch({
            userData: cardData,
            setUsers,
            setState,
            currentFilter,
            isDateInRange,
            submitOptions,
            trailingActions: getInTouchReactionActions,
            updateContext,
          })}
        </div>
        {!hasHiddenCycleFieldRole && (
          <div style={statusItemStyle}>
            <FieldLastCycle userData={cardData} setUsers={setUsers} setState={setState} submitOptions={submitOptions} />
          </div>
        )}
      </div>
      <div style={bioSectionStyle}>
        {/* Два рядки, а не один на перенос: хто людина (вік, статус, група,
            метрики) і що з нею вже було (пологи, регіон). Ділити рядок віддали
            не переносу, а змісту — інакше крапка-роздільник регулярно лишалась
            висіти першою в новому рядку. */}
        <div style={bioRowStyle}>
          {joinBioFacts([
            cardData.birth && (
              <span key="birth" style={factChipStyle}>
                {/* У базі дата лежить у `РРРР-ММ-ДД`; людині вона показується
                    крапками — так само, як усюди в застосунку. `birth` — теж
                    поле з історією (`getCurrentValue`): масив версій сюди
                    приїжджає, коли дату вже редагували, і без розгортання
                    `formatDateToDisplay` не впізнавав у ньому рядок — дата
                    лишалась нечитаною, а вік узагалі не рахувався. Адмін
                    бачить усі версії дати (`formatValueVersions`), вік —
                    з поточної. */}
                {formatValueVersions(cardData.birth, formatDateToDisplay)} {fieldBirth(cardData.birth)}
              </span>
            ),
            identityMeta.length > 0 && (
              <div key="identity" style={{ ...factChipStyle, ...identityMetaStyle }}>{identityMeta}</div>
            ),
          ])}
        </div>
        {(deliveryInfo || region) && (
          <div style={bioRowStyle}>
            {joinBioFacts([
              deliveryInfo && <div key="delivery" style={factChipStyle}>{deliveryInfo}</div>,
              region && <div key="region" style={factChipStyle}>{region}</div>,
            ])}
          </div>
        )}
        {renderOverlayEntries(['birth', 'maritalStatus', 'blood', 'height', 'weight'])}
        {renderOverlayEntries(['lastDelivery', 'ownKids'])}
        {renderOverlayEntries('region')}
      </div>
      <div style={contactsSectionStyle}>
        {fieldContacts(cardData)}
        {renderOverlayEntries(['phone', 'phone2', 'phone3', 'telegram', 'email', 'facebook', 'instagram', 'ameblo', 'tiktok', 'linkedin', 'youtube', 'twitter', 'line', 'otherLink', 'vk'])}
      </div>
      <div style={commentsSectionStyle}>
        {fieldWriter({ userData: cardData, setUsers, setState, submitOptions, updateContext })}
        <FieldComment
          userData={cardData}
          extendedMode={extendedMode}
          onLegacyCommentMigrated={() => {
            const removeLegacyComment = user => {
              if (!user) return user;
              const nextUser = { ...user };
              delete nextUser.myComment;
              return nextUser;
            };
            if (typeof setUsers === 'function') {
              setUsers(prev => updateUserInState(prev, cardData.userId, removeLegacyComment));
            }
            if (typeof setState === 'function' && !isFromListOfUsers) {
              setState(prev => removeLegacyComment(prev));
            }
          }}
        />
        {otherAdminsComments.map(comment => (
          <div key={comment.commentId || `${comment.authorId}-${comment.text}`} style={multiCommentRowStyle}>
            <button
              type="button"
              style={commentAuthorButtonStyle}
              title="Відкрити автора коментаря в режимі редагування"
              aria-label="Відкрити автора коментаря в режимі редагування"
              onClick={event => {
                event.stopPropagation();
                openAuthorCardForEdit(comment.authorId);
              }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                <circle cx="12" cy="8" r="4" stroke="currentColor" strokeWidth="1.8" />
                <path d="M5 20a7 7 0 0 1 14 0" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
              </svg>
            </button>
            <div
              style={multiCommentStyle}
              title="Редагувати коментар multiData"
              onClick={event => {
                event.stopPropagation();
                setSelectedComment(comment);
                setEditableComment(comment.text);
                setIsCommentModalOpen(true);
              }}
            >
              <span style={commentDateStyle}>{`${formatCommentDate(comment.lastAction) || '--.--.----'} · `}</span>
              {comment.text}
            </div>
            {isAdmin && comment.ownerId && (
              <button
                type="button"
                style={commentDeleteButtonStyle}
                title="Видалити оригінальний коментар"
                aria-label="Видалити оригінальний коментар"
                onClick={event => {
                  event.stopPropagation();
                  setCommentToDelete(comment);
                }}
              >
                ×
              </button>
            )}
          </div>
        ))}
        {publicCommentsFailed && (
          <button
            type="button"
            style={publicCommentsRetryButtonStyle}
            onClick={retryPublicComments}
            disabled={publicCommentsLoading}
            title="Повторити читання публічних відгуків"
          >
            {publicCommentsLoading ? 'Завантаження…' : '🌐 Показати відгуки'}
          </button>
        )}
        {publicComments.map(comment => {
          const canModify = canModifyPublicComment(comment);
          return (
            <div key={`public-${comment.id}`} style={publicCommentRowStyle}>
              <span
                style={publicCommentBadgeStyle}
                title="Публічний відгук — його бачить кожен користувач бази"
                aria-label="Публічний відгук"
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="1.8" />
                  <path d="M3 12h18" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
                  <path
                    d="M12 3a14 14 0 0 1 0 18a14 14 0 0 1 0-18z"
                    stroke="currentColor"
                    strokeWidth="1.8"
                    strokeLinejoin="round"
                  />
                </svg>
              </span>
              <div
                style={{ ...publicCommentStyle, cursor: canModify ? 'pointer' : 'default' }}
                title={canModify ? 'Редагувати публічний відгук' : 'Публічний відгук'}
                onClick={event => {
                  event.stopPropagation();
                  if (!canModify) return;
                  setSelectedComment({ kind: 'public', commentId: comment.id, text: comment.text });
                  setEditableComment(comment.text);
                  setIsCommentModalOpen(true);
                }}
              >
                <span style={commentDateStyle}>{`${formatCommentDate(comment.createdAt) || '--.--.----'} · `}</span>
                <span style={publicCommentAuthorStyle}>{comment.authorName || 'без імені'}</span>
                {`: ${comment.text}`}
              </div>
              {canModify && (
                <button
                  type="button"
                  style={commentDeleteButtonStyle}
                  title="Видалити публічний відгук"
                  aria-label="Видалити публічний відгук"
                  onClick={event => {
                    event.stopPropagation();
                    setCommentToDelete({
                      kind: 'public', commentId: comment.id, text: comment.text, authorId: comment.authorId,
                    });
                  }}
                >
                  ×
                </button>
              )}
            </div>
          );
        })}
      </div>
      {isPhotosModalOpen && (() => {
        const photosModalContent = (
          <div
            style={inlineModalOverlayStyle}
            onClick={event => {
              event.stopPropagation();
              setIsPhotosModalOpen(false);
            }}
          >
            <div
              style={photosModalCardStyle}
              onClick={event => event.stopPropagation()}
            >
              <div style={photosModalHeaderStyle}>
                <div>
                  <h3 style={photosModalTitleStyle}>Фото профілю</h3>
                  <p style={photosModalSubtitleStyle}>
                    {buildName(cardData) || cardData.userId || 'Користувач'}
                  </p>
                </div>
                <button
                  type="button"
                  style={photosModalCloseButtonStyle}
                  onClick={() => setIsPhotosModalOpen(false)}
                  aria-label="Закрити фото"
                  title="Закрити"
                >
                  ×
                </button>
              </div>
              <Photos
                state={cardData}
                setState={setCardPhotosState}
                uploadInputId={`file-upload-${cardData.userId || 'card'}`}
                cropAspectRatio={2 / 3}
              />
            </div>
          </div>
        );

        return typeof document !== 'undefined'
          ? createPortal(photosModalContent, document.body)
          : photosModalContent;
      })()}
      {isCommentModalOpen && typeof document !== 'undefined' && createPortal(
        <div
          style={inlineModalOverlayStyle}
          onClick={event => {
            event.stopPropagation();
            setIsCommentModalOpen(false);
            setSelectedComment(null);
          }}
        >
          <div
            style={inlineModalCardStyle}
            onClick={event => event.stopPropagation()}
          >
            {/* Заголовок каже, що саме зараз правиться: у списку рядки стоять
                поруч, а наслідок правки в них різний — нотатку бачать адміни,
                відгук бачать усі. */}
            <strong>
              {selectedComment?.kind === 'public' ? 'Публічний відгук — його бачать усі' : 'Коментар з multiData'}
            </strong>
            <textarea
              value={editableComment}
              onChange={event => setEditableComment(event.target.value)}
              style={inlineModalTextareaStyle}
            />
            <div style={inlineModalActionsStyle}>
              <button
                type="button"
                style={modalCancelButtonStyle}
                onClick={() => {
                  setIsCommentModalOpen(false);
                  setSelectedComment(null);
                }}
              >
                Скасувати
              </button>
              <button type="button" style={modalSaveButtonStyle} onClick={saveMultiComment}>
                Зберегти
              </button>
            </div>
          </div>
        </div>,
        document.body
      )}
      {commentToDelete && typeof document !== 'undefined' && createPortal(
        <div
          style={inlineModalOverlayStyle}
          onClick={event => {
            event.stopPropagation();
            setCommentToDelete(null);
          }}
        >
          <div
            style={inlineModalCardStyle}
            onClick={event => event.stopPropagation()}
          >
            <strong>Підтвердження видалення</strong>
            <div style={deleteModalTextStyle}>
              {commentToDelete?.kind === 'public'
                ? 'Видалити публічний відгук? Його більше не побачить ніхто.'
                : 'Ви впевнені, що хочете видалити цей коментар?'}
            </div>
            <div style={inlineModalActionsStyle}>
              <button
                type="button"
                style={modalCancelButtonStyle}
                onClick={() => {
                  setCommentToDelete(null);
                }}
              >
                Скасувати
              </button>
              <button
                type="button"
                style={modalDeleteButtonStyle}
                onClick={async () => {
                  await handleDeleteComment(commentToDelete);
                  setCommentToDelete(null);
                }}
              >
                Видалити
              </button>
            </div>
          </div>
        </div>,
        document.body
      )}

    </div>
  );
};

export const renderTopBlock = ({
  userData,
  setUsers,
  setShowInfoModal,
  setState,
  setUserIdToDelete,
  isFromListOfUsers,
  favoriteUsers = {},
  setFavoriteUsers,
  dislikeUsers = {},
  setDislikeUsers = () => {},
  currentFilter,
  isDateInRange,
  onOpenMedications,
  setSearch = null,
  topBlueAction = null,
  additionalActions = null,
  overlayFieldAdditions = {},
  onSubmitHistorySnapshot = null,
  stimulationScheduleToggle = null,
}) => (
  <TopBlock
    userData={userData}
    setUsers={setUsers}
    setShowInfoModal={setShowInfoModal}
    setState={setState}
    setUserIdToDelete={setUserIdToDelete}
    isFromListOfUsers={isFromListOfUsers}
    favoriteUsers={favoriteUsers}
    setFavoriteUsers={setFavoriteUsers}
    dislikeUsers={dislikeUsers}
    setDislikeUsers={setDislikeUsers}
    currentFilter={currentFilter}
    isDateInRange={isDateInRange}
    onOpenMedications={onOpenMedications}
    setSearch={setSearch}
    topBlueAction={topBlueAction}
    additionalActions={additionalActions}
    overlayFieldAdditions={overlayFieldAdditions}
    onSubmitHistorySnapshot={onSubmitHistorySnapshot}
    stimulationScheduleToggle={stimulationScheduleToggle}
  />
);
