import { handleChange } from './actions';
import { utilCalculateMonthsAgo } from './utilCalculateMonthsAgo';
import { AttentionButton } from 'components/styles';
import { formatDateToDisplay } from 'components/inputValidations';
import { getCurrentValue } from '../getCurrentValue';
import { formatValueVersions } from './valueVersions';

export const fieldDeliveryInfo = (args, legacySetState, legacyUserData, legacySubmitOptions = {}) => {
  const {
    setUsers,
    setState,
    userData,
    submitOptions = {},
  } = args && typeof args === 'object' && 'userData' in args
    ? args
    : {
        setUsers: args,
        setState: legacySetState,
        userData: legacyUserData,
        submitOptions: legacySubmitOptions,
      };
  const { csection } = userData;
  // Поля з історією версій: рахунок (місяці від пологів) — з поточної версії,
  // а показ — усі версії у форматі скаляра, зі стиранням («… → стерто»).
  const lastDelivery = getCurrentValue(userData.lastDelivery);
  const ownKidsText = formatValueVersions(userData.ownKids);
  const lastDeliveryText = formatValueVersions(userData.lastDelivery, formatDateToDisplay);
  const formattedLastDelivery = formatDateToDisplay(lastDelivery);

  const csectionItems = Array.isArray(csection)
    ? csection.filter(item => item !== null && item !== undefined)
    : csection !== null && csection !== undefined
    ? [csection]
    : [];

  const csectionText = csectionItems
    .map(item => item.toString().trim())
    .filter(Boolean)
    .join(', ');

  // Функція для парсингу дати з формату дд.мм.рррр
  const parseCsectionDate = dateString => {
    // Перевірка формату дд.мм.рррр
    const dateRegex = /^\d{2}\.\d{2}\.\d{4}$/;

    if (!dateRegex.test(dateString)) {
      return null; // Повертаємо null, якщо формат не відповідає
    }

    const [day, month, year] = dateString.split('.').map(Number);

    // Перевірка на коректність дати
    const isValidDate = (d, m, y) => d > 0 && d <= 31 && m > 0 && m <= 12 && y > 0 && !isNaN(new Date(y, m - 1, d).getTime());

    if (!isValidDate(day, month, year)) {
      return null; // Повертаємо null, якщо дата некоректна
    }

    return dateString;
  };

  // Використовуємо `csection` як дату останніх пологів, якщо `lastDelivery` не задано
  const csectionDate = csectionItems
    .map(item => item.toString().trim())
    .find(item => parseCsectionDate(item));

  const effectiveLastDelivery = formattedLastDelivery || csectionDate || null;

  // Додаємо перевірку перед викликом `split`
  let deliveryDate = null;
  if (effectiveLastDelivery && /^\d{2}\.\d{2}\.\d{4}$/.test(effectiveLastDelivery)) {
    const [day, month, year] = effectiveLastDelivery.split('.').map(Number);
    deliveryDate = new Date(year, month - 1, day); // JavaScript місяці починаються з 0
  }

  const monthsAgo = effectiveLastDelivery ? utilCalculateMonthsAgo(effectiveLastDelivery) : null;
  const daysUntilDelivery = (() => {
    if (!deliveryDate) return null;
    const now = new Date();
    if (deliveryDate <= now) return null;
    const diffMs = deliveryDate.getTime() - now.getTime();
    return Math.ceil(diffMs / (1000 * 60 * 60 * 24));
  })();

  const monthsToAdd = (() => {
    const val = csectionItems
      .map(item => item.toString().toLowerCase().replace(/\s/g, ''))
      .find(Boolean) || '';
    return ['кс-', '-', 'no', 'ні', '0'].includes(val) ? 9 : 18;
  })();

  const whenGetInTouch = deliveryDate
    ? new Date(deliveryDate.getFullYear(), deliveryDate.getMonth() + monthsToAdd, deliveryDate.getDate())
    : null;

  // Форматування дати у формат "дд.мм.рррр"
  const formatDate = date =>
    date
      ? date
          .toLocaleDateString('uk-UA', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
          })
          .replace(/\//g, '.')
      : null;

  if (!ownKidsText && !lastDeliveryText && monthsAgo === null && !csectionText) return null;

  const parts = [];
  const deliveryText = lastDeliveryText || effectiveLastDelivery;
  if (deliveryText) parts.push(`${deliveryText} пологи`);

  if (monthsAgo !== null) {
    if (monthsAgo > 24) {
      const years = Math.floor(monthsAgo / 12); // Округлення до меншого
      parts.push(`${years}рт, `);
    } else {
      parts.push(`${monthsAgo}м, `);
      if (daysUntilDelivery !== null) {
        parts[parts.length - 1] = parts[parts.length - 1].replace(
          /, $/,
          `/${daysUntilDelivery}д, `,
        );
      }
    }
  }

  if (ownKidsText) parts.push(`всього ${ownKidsText},`);

  // Повертаємо результат
  return (
    <div style={{ display: 'flex', alignItems: 'baseline', gap: '5px', flexWrap: 'wrap', minWidth: 0 }}>
      {parts.map((part, index) => (
        <span key={`part-${index}`} style={{ whiteSpace: 'nowrap' }}>
          {part}
        </span>
      ))}
      {csectionText && (
        <AttentionButton
          key="csection"
          onClick={() => {
            handleChange(
              setUsers,
              setState,
              userData.userId,
              'getInTouch',
              formatDate(whenGetInTouch),
              true,
              submitOptions,
            );
          }}
        >
          кс {csectionText}
        </AttentionButton>
      )}
    </div>
  );
};

